{
  "terms": [
    {
      "id": "irl",
      "label": "information request letters",
      "aliases": [
        "IRLs"
      ],
      "source_refs": [
        "F002",
        "F003"
      ]
    },
    {
      "id": "in",
      "label": "information notices",
      "aliases": [
        "INs"
      ],
      "source_refs": [
        "F002",
        "F007"
      ]
    }
  ],
  "extractions": [
    {
      "unit": "F002",
      "unit_attributes": {
        "defines_term": null,
        "term_refs": [
          "irl",
          "in"
        ],
        "statement": "The purpose of this subchapter is to provide guidance regarding the use of information request letters (IRLs) and information notices (INs).",
        "actor": null,
        "actor_quote": null,
        "kind": "statement",
        "modality": "not_stated"
      }
    },
    {
      "unit": "F003",
      "unit_attributes": {
        "defines_term": "irl",
        "term_refs": [
          "irl"
        ],
        "statement": "IRLs are personalized, standardized letters with a date and signature block that request from the applicant additional information, documentation, or action needed to process the passport application.",
        "actor": null,
        "actor_quote": null,
        "kind": "definition",
        "modality": "not_stated"
      }
    },
    {
      "unit": "F003",
      "unit_attributes": {
        "defines_term": null,
        "term_refs": [
          "irl"
        ],
        "statement": "You must fully adjudicate the passport application prior to suspending to ensure that you are addressing all issues.",
        "actor": "You",
        "actor_quote": "You",
        "kind": "requirement",
        "modality": "must",
        "modality_quote": "must"
      }
    },
    {
      "unit": "F003",
      "unit_attributes": {
        "defines_term": null,
        "term_refs": [
          "irl"
        ],
        "statement": "The IRLs have been carefully crafted to communicate clearly and accurately statutory, regulatory, and other requirements of the Department.",
        "actor": null,
        "actor_quote": null,
        "kind": "statement",
        "modality": "not_stated"
      }
    },
    {
      "unit": "F004",
      "unit_attributes": {
        "defines_term": null,
        "term_refs": [
          "irl"
        ],
        "statement": "Passport agencies/centers must not make unilateral changes or alterations to the IRLs without the approval of the Office of Adjudication (CA/PPT/S/A), except on a case-by-case basis with the approval of passport agency/center management in extenuating circumstances (e.g., when you request that the applicant submit a birth certificate instead of a notification of birth registration, and the applicant insists that the notification of birth registration is the birth certificate).",
        "actor": "Passport agencies/centers",
        "actor_quote": "Passport agencies/centers",
        "kind": "prohibition",
        "modality": "must_not",
        "modality_quote": "must not"
      }
    },
    {
      "unit": "F005",
      "unit_attributes": {
        "defines_term": null,
        "term_refs": [
          "irl"
        ],
        "statement": "Posts must use the cleared language in the IRLs.",
        "actor": "Posts",
        "actor_quote": "Posts",
        "kind": "requirement",
        "modality": "must",
        "modality_quote": "must"
      }
    },
    {
      "unit": "F005",
      "unit_attributes": {
        "defines_term": null,
        "term_refs": [
          "irl"
        ],
        "statement": "Posts are authorized to modify the language in the IRLs to suit local logistical requirements and other local concerns such as available documentation.",
        "actor": "Posts",
        "actor_quote": "Posts",
        "kind": "authority",
        "modality": "may",
        "modality_quote": "are authorized"
      }
    },
    {
      "unit": "F006",
      "unit_attributes": {
        "defines_term": null,
        "term_refs": [
          "irl"
        ],
        "statement": "IRLs are not adjudicative guidance.",
        "actor": null,
        "actor_quote": null,
        "kind": "statement",
        "modality": "not_stated"
      }
    },
    {
      "unit": "F006",
      "unit_attributes": {
        "defines_term": null,
        "term_refs": [
          "irl"
        ],
        "statement": "The passport application must be adjudicated in accordance with the 8 FAM and then the appropriate IRL selected to address any deficiencies with the passport or Consular Report of Birth Abroad (CRBA).",
        "actor": null,
        "actor_quote": null,
        "kind": "requirement",
        "modality": "must",
        "modality_quote": "must",
        "references": [
          "8 FAM"
        ]
      }
    },
    {
      "unit": "F007",
      "unit_attributes": {
        "defines_term": "in",
        "term_refs": [
          "in"
        ],
        "statement": "INs are standardized notices that provide passport bearers with information about their passports.",
        "actor": null,
        "actor_quote": null,
        "kind": "definition",
        "modality": "not_stated"
      }
    },
    {
      "unit": "F007",
      "unit_attributes": {
        "defines_term": null,
        "term_refs": [
          "in"
        ],
        "statement": "As an example, an IN may be included to explain why the passport was limited in validity, and/or what documentation is needed to obtain a fully valid passport.",
        "actor": null,
        "actor_quote": null,
        "kind": "statement",
        "modality": "possible",
        "modality_quote": "may"
      }
    },
    {
      "unit": "F007",
      "unit_attributes": {
        "defines_term": null,
        "term_refs": [
          "in"
        ],
        "statement": "The INs have been carefully crafted to communicate information about their passports clearly and accurately.",
        "actor": null,
        "actor_quote": null,
        "kind": "statement",
        "modality": "not_stated"
      }
    },
    {
      "unit": "F007",
      "unit_attributes": {
        "defines_term": null,
        "term_refs": [
          "in"
        ],
        "statement": "No changes or alterations to the INs may be made unilaterally at passport agencies/centers without the approval of CA/PPT/S/A, except in extenuating circumstances on a case-by-case basis with the approval of passport agency/center management (e.g., when using an endorsement 46 to limit a passport for a special problem).",
        "actor": "passport agencies/centers",
        "actor_quote": "passport agencies/centers",
        "kind": "prohibition",
        "modality": "must_not",
        "modality_quote": "no changes or alterations to the INs may be made"
      }
    },
    {
      "unit": "F007",
      "unit_attributes": {
        "defines_term": null,
        "term_refs": [
          "in"
        ],
        "statement": "INs do not require a response from the applicant and do not need to be personalized with the applicant's name and address.",
        "actor": null,
        "actor_quote": null,
        "kind": "exemption",
        "modality": "not_required",
        "modality_quote": "do not require"
      }
    },
    {
      "unit": "F008",
      "unit_attributes": {
        "defines_term": null,
        "term_refs": [
          "irl",
          "in"
        ],
        "statement": "When tailoring correspondence to a situation, Posts may consult Passport Services’ IRL index and IN Index or contact AskPPTAdjudication@state.gov.",
        "actor": "Posts",
        "actor_quote": "Posts",
        "kind": "permission",
        "modality": "may",
        "modality_quote": "may",
        "choice_text": "When tailoring correspondence to a situation, Posts may choose to consult Passport Services' IRL index and IN Index, or contact AskPPTAdjudication@state.gov."
      }
    }
  ]
}
